// CWE-1321: merge, set and parse functions never change Object.prototype (or Array.prototype, Function.prototype).
import * as fc from 'fast-check';
import { show } from './cwe.ts';
import { securityLaw } from './law.ts';
import type { SecurityLaw } from './law.ts';

/** Hostile JSON text for a law parameter. Generated by `pollutionPayloads`. */
export type PollutionPayload = string & { readonly __tslawsPollution: true };
/** A hostile dotted path (`a.__proto__.x`) for a law parameter. Generated by `pollutionPaths`. */
export type PollutionPath = string & { readonly __tslawsPollutionPath: true };

/** The property every payload tries to plant. */
export const marker = 'tslawsPolluted';

const dangerous = ['__proto__', 'constructor', 'prototype'] as const;

// Key chains that reach a shared prototype from a plain object, from an array and from a function.
const chains: readonly (readonly string[])[] = [
  ['__proto__'],
  ['constructor', 'prototype'],
  ['__proto__', '__proto__'],
  ['a', '__proto__'],
  ['a', 'constructor', 'prototype'],
  ['a', 'b', '__proto__'],
  ['constructor', 'prototype', 'constructor', 'prototype'],
];

function nest(keys: readonly string[], leaf: unknown): string {
  return JSON.stringify(keys.reduceRight<unknown>((inner, key) => ({ [key]: inner }), leaf));
}

/** JSON objects whose keys walk to a shared prototype and plant `tslawsPolluted`; `JSON.parse` makes `__proto__` an own key. */
export function pollutionPayloads(): fc.Arbitrary<PollutionPayload> {
  const chain = fc
    .tuple(fc.array(fc.constantFrom('a', 'b', ...dangerous), { maxLength: 2 }), fc.constantFrom(...chains))
    .map(([lead, tail]) => [...lead, ...tail]);
  return fc
    .oneof(
      { weight: 5, arbitrary: chain.map((keys) => nest(keys, { [marker]: 'yes' })) },
      { weight: 2, arbitrary: chain.map((keys) => nest(keys, [{ [marker]: 'yes' }])) },
      { weight: 2, arbitrary: chain.map((keys) => `{"keep":1,"list":[${nest(keys, { [marker]: 'yes' })}]}`) },
    )
    .map((text) => text as PollutionPayload);
}

/** Dotted paths that walk through a prototype key to `tslawsPolluted`. */
export function pollutionPaths(): fc.Arbitrary<PollutionPath> {
  return fc
    .tuple(fc.array(fc.constantFrom('a', 'b'), { maxLength: 2 }), fc.constantFrom(...chains))
    .map(([lead, tail]) => [...lead, ...tail, marker].join('.') as PollutionPath);
}

/** The fixed JSON attacks `merge` and `parse` laws check on every call. */
export const pollutionCorpus: readonly PollutionPayload[] = [
  `{"__proto__":{"${marker}":"yes"}}`,
  `{"constructor":{"prototype":{"${marker}":"yes"}}}`,
  `{"a":{"__proto__":{"${marker}":"yes"}}}`,
  `{"a":{"constructor":{"prototype":{"${marker}":"yes"}}}}`,
  `{"list":[{"__proto__":{"${marker}":"yes"}}]}`,
  `{"__proto__":{"__proto__":{"${marker}":"yes"}}}`,
].map((text) => text as PollutionPayload);

/** The fixed paths `set` laws check on every call. */
export const pollutionPathCorpus: readonly PollutionPath[] = [
  `__proto__.${marker}`,
  `constructor.prototype.${marker}`,
  `a.__proto__.${marker}`,
  `a.constructor.prototype.${marker}`,
  `__proto__.__proto__.${marker}`,
].map((text) => text as PollutionPath);

const shared: readonly [string, object][] = [
  ['Object.prototype', Object.prototype],
  ['Array.prototype', Array.prototype],
  ['Function.prototype', Function.prototype],
];

type Saved = [string, object, Map<string | symbol, PropertyDescriptor>];

function save(): Saved[] {
  return shared.map(([name, target]) => {
    const props = new Map<string | symbol, PropertyDescriptor>();
    for (const key of Reflect.ownKeys(target)) props.set(key, Object.getOwnPropertyDescriptor(target, key)!);
    return [name, target, props];
  });
}

function same(a: PropertyDescriptor, b: PropertyDescriptor): boolean {
  return (
    Object.is(a.value, b.value) &&
    a.get === b.get &&
    a.set === b.set &&
    a.writable === b.writable &&
    a.enumerable === b.enumerable
  );
}

/** What changed on the shared prototypes since `save`; puts them back so one failure does not poison the process. */
function restore(saved: Saved[]): string | undefined {
  let found: string | undefined;
  for (const [name, target, props] of saved) {
    for (const key of Reflect.ownKeys(target)) {
      const now = Object.getOwnPropertyDescriptor(target, key)!;
      const before = props.get(key);
      if (before !== undefined && same(before, now)) continue;
      found ??= `${name}.${String(key)} was ${before === undefined ? 'added' : 'changed'}`;
      try {
        if (before === undefined) delete (target as Record<string | symbol, unknown>)[key];
        else Object.defineProperty(target, key, before);
      } catch {
        // A frozen prototype cannot be written, so nothing changed.
      }
    }
  }
  return found;
}

function guarded(input: string, call: string, act: () => void): { detail: string } | undefined {
  const saved = save();
  try {
    act();
  } catch {
    // A function that refuses the input is safe; only a change to a prototype counts.
  }
  const changed = restore(saved);
  if (changed !== undefined) return { detail: `${call}(${show(input)}) polluted: ${changed}` };
  return undefined;
}

/** CWE-1321 for `merge(target, source)`: merging parsed hostile JSON into an object must leave the shared prototypes alone. */
export function prototypeSafeMerge(merge: (target: any, source: any) => unknown): SecurityLaw<PollutionPayload> {
  return securityLaw<PollutionPayload>({
    id: 'prototype-safe-merge',
    cwe: ['CWE-1321'],
    title: 'a merge never changes Object.prototype on __proto__ or constructor.prototype keys',
    input: pollutionPayloads(),
    corpus: pollutionCorpus,
    verdict: (input) => guarded(input, 'merge', () => void merge({}, JSON.parse(input))),
  });
}

export interface PrototypeSafeSetOptions {
  /** `dotted` (default): `set(target, 'a.b', value)`. `array`: `set(target, ['a', 'b'], value)`. */
  pathFormat?: 'dotted' | 'array';
}

/** CWE-1321 for `set(target, path, value)`: a path through `__proto__` or `constructor.prototype` must not reach a shared prototype. */
export function prototypeSafeSet(
  set: (target: any, path: any, value: unknown) => unknown,
  options: PrototypeSafeSetOptions = {},
): SecurityLaw<PollutionPath> {
  const asArray = options.pathFormat === 'array';
  return securityLaw<PollutionPath>({
    id: 'prototype-safe-set',
    cwe: ['CWE-1321'],
    title: 'a path setter never changes Object.prototype on __proto__ or constructor.prototype paths',
    input: pollutionPaths(),
    corpus: pollutionPathCorpus,
    verdict: (input) => guarded(input, 'set', () => void set({}, asArray ? input.split('.') : input, 'yes')),
  });
}

/** CWE-1321 for `parse(text)`: parsing hostile JSON (a parser that merges, revives or assigns by key) must leave the shared prototypes alone. */
export function prototypeSafeParse(parse: (text: string) => unknown): SecurityLaw<PollutionPayload> {
  return securityLaw<PollutionPayload>({
    id: 'prototype-safe-parse',
    cwe: ['CWE-1321'],
    title: 'a parser never changes Object.prototype on __proto__ or constructor.prototype keys',
    input: pollutionPayloads(),
    corpus: pollutionCorpus,
    verdict: (input) => guarded(input, 'parse', () => void parse(input)),
  });
}
